-- Isolated in-memory PostgreSQL fixture. Never execute against Cloud.
CREATE ROLE anon; CREATE ROLE authenticated; CREATE ROLE service_role BYPASSRLS;
CREATE SCHEMA auth; CREATE SCHEMA extensions;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
CREATE TABLE auth.users(id uuid PRIMARY KEY,email text,email_confirmed_at timestamptz);
CREATE FUNCTION extensions.gen_random_bytes(n int) RETURNS bytea LANGUAGE sql AS $$ SELECT decode(md5(random()::text),'hex') $$;
CREATE TABLE public.user_roles(user_id uuid,role text);
CREATE TABLE public.series_managers(user_id uuid,series_id uuid);
CREATE FUNCTION public.has_role(uid uuid,r text) RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=uid AND role=r) $$;
CREATE FUNCTION public.manages_series(uid uuid,sid uuid) RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT EXISTS(SELECT 1 FROM public.series_managers WHERE user_id=uid AND series_id=sid) $$;
CREATE TABLE public.events(id uuid PRIMARY KEY,title text,date date,status text,sold_out boolean,is_16plus boolean,series_id uuid,service_fee_enabled boolean,service_fee_type text,service_fee_value numeric,service_fee_vat numeric,service_fee_mode text,insurance_enabled boolean,insurance_amount numeric);
CREATE TABLE public.ticket_categories(id uuid PRIMARY KEY,event_id uuid,name text,price numeric,sold_out boolean,internal_only boolean,coming_soon boolean,sale_start timestamptz,sale_end timestamptz,max_capacity int,group_size int);
CREATE TABLE public.orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text,name text,phone text,birth_date date,event_id uuid,items jsonb,total_amount numeric,currency text,service_fee numeric,insurance_fee numeric,status text,mollie_payment_id text,stripe_payment_id text,redirect_url text,created_at timestamptz DEFAULT now(),paid_at timestamptz);
CREATE TABLE public.tickets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid,event_id uuid,ticket_category_id uuid,holder_name text,holder_email text,qr_code text UNIQUE,status text,checked_in_at timestamptz);
CREATE TABLE public.coupons(id uuid PRIMARY KEY,code text,active boolean,event_id uuid,max_uses int,used_count int DEFAULT 0,valid_from timestamptz,valid_until timestamptz,min_order_amount numeric,discount_type text,discount_value numeric);
CREATE TABLE public.scanner_links(id uuid,token text,active boolean,event_id uuid,label text,expires_at timestamptz);
CREATE TABLE public.u18_forms(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_id uuid,event_title text,event_date timestamptz,parent_name text,parent_address text,parent_zip text,parent_city text,parent_country text,parent_phone text,parent_birthday date,minor_name text,minor_address text,minor_zip text,minor_city text,minor_country text,minor_phone text,minor_birthday date,supervisor_name text,supervisor_address text,supervisor_zip text,supervisor_city text,supervisor_country text,supervisor_email text,supervisor_phone text,supervisor_birthday date,email text,has_signature boolean,has_supervisor_signature boolean,accept_newsletter boolean,parent_signature text,supervisor_signature text);
CREATE TABLE public.settings(key text PRIMARY KEY,value jsonb,updated_at timestamptz);
CREATE TABLE public.ticket_transfers(ticket_id uuid,from_user_id uuid,from_email text,to_email text,to_name text,message text,status text,completed_at timestamptz);
CREATE FUNCTION public.award_loyalty_for_paid_order_backfill(r public.orders) RETURNS void LANGUAGE sql AS $$ SELECT $$;
ALTER TABLE public.orders ENABLE ROW LEVEL SECURITY; ALTER TABLE public.tickets ENABLE ROW LEVEL SECURITY; ALTER TABLE public.scanner_links ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Anyone can create orders" ON public.orders FOR INSERT TO anon WITH CHECK(status='pending');
CREATE POLICY "Anyone can view active scanner links" ON public.scanner_links FOR SELECT TO anon USING(active);
CREATE POLICY "Customers view own orders" ON public.orders FOR SELECT TO authenticated USING(true);
CREATE POLICY "Customers view own tickets" ON public.tickets FOR SELECT TO authenticated USING(true);
CREATE POLICY "Series managers can view tickets of their series" ON public.tickets FOR SELECT TO authenticated USING(true);
CREATE POLICY "Scanners can update ticket status" ON public.tickets FOR UPDATE TO authenticated USING(true);
GRANT USAGE ON SCHEMA public,auth TO anon,authenticated,service_role;
GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA public TO authenticated;
GRANT SELECT,INSERT ON public.orders TO anon; GRANT SELECT ON public.scanner_links TO anon;
GRANT ALL ON ALL TABLES IN SCHEMA public TO service_role;

CREATE TABLE public.page_visits(id uuid,session_id text,page_url text,referrer text,referrer_source text,user_agent text,left_at timestamptz);
ALTER TABLE public.settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Anyone can read settings" ON public.settings FOR SELECT TO public USING(true);
CREATE POLICY "Admins manage settings" ON public.settings FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
GRANT SELECT ON public.settings TO anon;
ALTER TABLE public.u18_forms ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Anyone can submit u18 form" ON public.u18_forms FOR INSERT TO public WITH CHECK(true);
GRANT INSERT ON public.u18_forms TO anon;
